-- Non-destructive SaaS product milestone. Existing user projects/pages are unchanged.

alter table public.projects add column if not exists kind text not null default 'website';
alter table public.projects drop constraint if exists projects_kind_check;
alter table public.projects add constraint projects_kind_check check(kind in ('website','app','game'));
create table if not exists public.starter_templates(
 id uuid primary key default gen_random_uuid(), name text not null unique,
 kind text not null check(kind in ('website','app','game')),description text not null,
 pages jsonb not null check(jsonb_typeof(pages)='array'),
 is_active boolean not null default true, created_at timestamptz not null default now()
);
alter table public.starter_templates enable row level security;
revoke all on public.starter_templates from anon,authenticated;
grant select on public.starter_templates to anon,authenticated;
drop policy if exists starter_templates_read on public.starter_templates;
create policy starter_templates_read on public.starter_templates for select to anon,authenticated using(is_active);
create table if not exists public.published_pages(
 project_id uuid not null references public.projects(id) on delete cascade,
 path text not null check(path ~ '^/[^?#]*$'),
 ui_tree jsonb not null check(jsonb_typeof(ui_tree)='array'),
 site_title text not null,
 is_live boolean not null default true,
 published_at timestamptz not null default now(),
 primary key(project_id,path)
);
alter table public.published_pages enable row level security;
revoke all on public.published_pages from anon,authenticated;
grant select on public.published_pages to anon,authenticated;
grant insert,update on public.published_pages to authenticated;
drop policy if exists published_public_read on public.published_pages;
create policy published_public_read on public.published_pages for select to anon,authenticated using(is_live);
drop policy if exists published_owner_read on public.published_pages;
create policy published_owner_read on public.published_pages for select to authenticated using(exists(select 1 from public.projects p where p.id=project_id and p.owner_id=(select auth.uid())));
drop policy if exists published_owner_insert on public.published_pages;
create policy published_owner_insert on public.published_pages for insert to authenticated with check(exists(select 1 from public.projects p where p.id=project_id and p.owner_id=(select auth.uid())));
drop policy if exists published_owner_update on public.published_pages;
create policy published_owner_update on public.published_pages for update to authenticated using(exists(select 1 from public.projects p where p.id=project_id and p.owner_id=(select auth.uid()))) with check(exists(select 1 from public.projects p where p.id=project_id and p.owner_id=(select auth.uid())));

