insert into public.starter_templates(name,kind,description,pages) values ('Mini game trắc nghiệm','game','Trò chơi tương tác có câu hỏi, chấm điểm và chơi lại.','[{"path":"/","ui_tree":[{"id":"seed-59","type":"hero","props":{},"style":{"backgroundColor":"#0f172a","color":"#ffffff","fontSize":"20","padding":"36","borderRadius":"24","gap":"12"},"children":[{"id":"seed-56","type":"h1","props":{"text":"Thử thách kiến thức"},"style":{"backgroundColor":"#0f172a","color":"#ffffff","fontSize":"36","padding":"14","borderRadius":"10","gap":"12"},"children":[]},{"id":"seed-57","type":"paragraph","props":{"text":"Trả lời câu hỏi để nhận điểm."},"style":{"backgroundColor":"#0f172a","color":"#cbd5e1","fontSize":"17","padding":"14","borderRadius":"12","gap":"12"},"children":[]},{"id":"seed-58","type":"button","props":{"text":"Bắt đầu","href":"#quiz"},"style":{"backgroundColor":"#f97316","color":"#ffffff","fontSize":"16","padding":"16","borderRadius":"14","gap":"12"},"children":[]}]},{"id":"seed-60","type":"quiz","props":{"title":"Trắc nghiệm","questions":"Thủ đô Việt Nam ở đâu?|Hà Nội|Huế|Đà Nẵng|Hải Phòng|1\n2 + 3 bằng mấy?|4|5|6|7|2"},"style":{"backgroundColor":"#eff6ff","color":"#1e3a8a","fontSize":"16","padding":"26","borderRadius":"20","gap":"12"},"children":[]}]}]'::jsonb) on conflict(name) do nothing;
